package com.apex.hrm.approvals;

import com.apex.hrm.platform.security.HrmUserPrincipal;
import com.apex.hrm.platform.tenant.TenantJdbcExecutor;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/v1/approvals")
public class ApprovalController {
    private final JdbcTemplate jdbc; private final TenantJdbcExecutor tenants; private final ApprovalWorkflowService engine;
    public ApprovalController(JdbcTemplate jdbc,TenantJdbcExecutor tenants,ApprovalWorkflowService engine){this.jdbc=jdbc;this.tenants=tenants;this.engine=engine;}
    public record CreateWorkflow(@NotBlank @Size(max=160) String name,@NotBlank String processCode){}
    public record StepInput(@Min(1) @Max(30) int stepNo,@NotBlank @Size(max=120) String label,@NotBlank String actionType,@NotBlank String approverType,String roleCode,UUID identityId,Integer managerDepth){}
    public record AssignmentInput(@NotBlank String processCode,UUID companyId,UUID departmentId,@NotNull UUID workflowVersionId){}
    public record DecisionInput(@NotBlank @Pattern(regexp="APPROVE|REJECT") String decision,@Size(max=10000) String comments,@Min(1) @Max(1440) Integer approvedMinutes){}
    private ResponseStatusException fail(HttpStatus s,String m){return new ResponseStatusException(s,m);}
    private boolean has(HrmUserPrincipal u,String role){return u!=null&&u.getAuthorities().stream().anyMatch(a->a.getAuthority().equals(role));}
    private void auth(HrmUserPrincipal u){if(u==null||!u.isEnabled()||!has(u,"ROLE_MFA_VERIFIED"))throw fail(HttpStatus.FORBIDDEN,"Verified workspace session required");}
    private void admin(HrmUserPrincipal u){auth(u);if(!has(u,"ROLE_TENANT_ADMIN")&&!has(u,"ROLE_HR_ADMIN"))throw fail(HttpStatus.FORBIDDEN,"Workflow administration requires tenant administrator or HR administrator");}
    @GetMapping("/processes") public List<Map<String,Object>> processes(@AuthenticationPrincipal HrmUserPrincipal u){admin(u);return tenants.inTenant(u.tenantId(),()->jdbc.queryForList("SELECT code,module,display_name,enabled FROM approval_process_type WHERE enabled ORDER BY module,display_name"));}
    @GetMapping("/exceptions") public List<Map<String,Object>> exceptions(@AuthenticationPrincipal HrmUserPrincipal u){admin(u);return tenants.inTenant(u.tenantId(),()->jdbc.queryForList("SELECT i.id,i.process_code,i.business_entity,i.business_id,i.summary,i.current_step,i.created_at,p.email AS requester_email,e.first_name,e.last_name,s.label AS failed_step FROM approval_instance i JOIN approval_process_type t ON t.code=i.process_code JOIN auth_identity p ON p.tenant_id=i.tenant_id AND p.id=i.requester_identity_id JOIN personnel_employee e ON e.tenant_id=i.tenant_id AND e.id=i.requester_employee_id LEFT JOIN approval_workflow_step s ON s.tenant_id=i.tenant_id AND s.workflow_version_id=i.workflow_version_id AND s.step_no=i.current_step WHERE i.tenant_id=? AND i.status='ROUTING_ERROR' ORDER BY i.created_at",u.tenantId()));}
    @GetMapping("/approvers") public List<Map<String,Object>> approvers(@AuthenticationPrincipal HrmUserPrincipal u){admin(u);return tenants.inTenant(u.tenantId(),()->jdbc.queryForList("SELECT i.id,i.email,array_agg(DISTINCT r.role ORDER BY r.role) AS roles FROM auth_identity i JOIN auth_identity_role r ON r.identity_id=i.id WHERE i.tenant_id=? AND i.enabled GROUP BY i.id,i.email ORDER BY i.email",u.tenantId()));}
    @GetMapping("/scopes/companies") public List<Map<String,Object>> companies(@AuthenticationPrincipal HrmUserPrincipal u){admin(u);return tenants.inTenant(u.tenantId(),()->jdbc.queryForList("SELECT id,company_code AS \"companyCode\",legal_name AS \"legalName\" FROM company WHERE tenant_id=? ORDER BY legal_name",u.tenantId()));}
    @GetMapping("/scopes/departments") public List<Map<String,Object>> departments(@AuthenticationPrincipal HrmUserPrincipal u,@RequestParam UUID companyId){admin(u);return tenants.inTenant(u.tenantId(),()->jdbc.queryForList("SELECT id,company_id AS \"companyId\",department_code AS code,department_name AS name FROM personnel_department WHERE tenant_id=? AND company_id=? ORDER BY department_name",u.tenantId(),companyId));}
    @GetMapping("/workflows") public List<Map<String,Object>> workflows(@AuthenticationPrincipal HrmUserPrincipal u){admin(u);return tenants.inTenant(u.tenantId(),()->jdbc.queryForList("""
SELECT w.id,w.name,w.process_code,w.status,w.created_at,v.id AS version_id,v.version_no,v.status AS version_status,v.published_at,(SELECT count(*) FROM approval_workflow_step s WHERE s.tenant_id=v.tenant_id AND s.workflow_version_id=v.id) AS step_count FROM approval_workflow w JOIN approval_workflow_version v ON v.tenant_id=w.tenant_id AND v.workflow_id=w.id WHERE w.tenant_id=? ORDER BY w.updated_at DESC,v.version_no DESC""",u.tenantId()));}
    @PostMapping("/workflows") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> create(@AuthenticationPrincipal HrmUserPrincipal u,@Valid @RequestBody CreateWorkflow in){admin(u);return tenants.inTenant(u.tenantId(),()->{if(!exists("SELECT EXISTS(SELECT 1 FROM approval_process_type WHERE code=? AND enabled)",in.processCode()))throw fail(HttpStatus.BAD_REQUEST,"Unknown business process");UUID id=UUID.randomUUID(),version=UUID.randomUUID();jdbc.update("INSERT INTO approval_workflow(id,tenant_id,name,process_code,created_by) VALUES(?,?,?,?,?)",id,u.tenantId(),in.name().trim(),in.processCode(),u.id());jdbc.update("INSERT INTO approval_workflow_version(id,tenant_id,workflow_id,version_no,created_by) VALUES(?,?,?,1,?)",version,u.tenantId(),id,u.id());audit(u,"APPROVAL_WORKFLOW_CREATED",id);return Map.of("id",id,"versionId",version,"versionNo",1);});}
    @PostMapping("/workflows/{id}/versions") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> newVersion(@AuthenticationPrincipal HrmUserPrincipal u,@PathVariable UUID id){admin(u);return tenants.inTenant(u.tenantId(),()->{List<Map<String,Object>> w=jdbc.queryForList("SELECT id FROM approval_workflow WHERE tenant_id=? AND id=? AND status<>'RETIRED'",u.tenantId(),id);if(w.isEmpty())throw fail(HttpStatus.NOT_FOUND,"Workflow not found");Integer no=jdbc.queryForObject("SELECT coalesce(max(version_no),0)+1 FROM approval_workflow_version WHERE tenant_id=? AND workflow_id=?",Integer.class,u.tenantId(),id);UUID version=UUID.randomUUID();jdbc.update("INSERT INTO approval_workflow_version(id,tenant_id,workflow_id,version_no,created_by) VALUES(?,?,?, ?,?)",version,u.tenantId(),id,no,u.id());jdbc.update("INSERT INTO approval_workflow_step(tenant_id,workflow_version_id,step_no,label,action_type,approver_type,role_code,identity_id,manager_depth) SELECT tenant_id,?,step_no,label,action_type,approver_type,role_code,identity_id,manager_depth FROM approval_workflow_step WHERE tenant_id=? AND workflow_version_id=(SELECT id FROM approval_workflow_version WHERE tenant_id=? AND workflow_id=? AND status='PUBLISHED' ORDER BY version_no DESC LIMIT 1)",version,u.tenantId(),u.tenantId(),id);audit(u,"APPROVAL_WORKFLOW_VERSION_CREATED",version);return Map.of("versionId",version,"versionNo",no);});}
    @GetMapping("/workflows/{id}/versions/{versionId}/steps") public List<Map<String,Object>> steps(@AuthenticationPrincipal HrmUserPrincipal u,@PathVariable UUID id,@PathVariable UUID versionId){admin(u);return tenants.inTenant(u.tenantId(),()->jdbc.queryForList("SELECT s.id,s.step_no,s.label,s.action_type,s.approver_type,s.role_code,s.identity_id,s.manager_depth,i.email AS identity_email FROM approval_workflow_step s JOIN approval_workflow_version v ON v.tenant_id=s.tenant_id AND v.id=s.workflow_version_id LEFT JOIN auth_identity i ON i.tenant_id=s.tenant_id AND i.id=s.identity_id WHERE s.tenant_id=? AND v.workflow_id=? AND s.workflow_version_id=? ORDER BY s.step_no",u.tenantId(),id,versionId));}
    @PutMapping("/workflows/{id}/versions/{versionId}/steps") public void steps(@AuthenticationPrincipal HrmUserPrincipal u,@PathVariable UUID id,@PathVariable UUID versionId,@Valid @RequestBody List<@Valid StepInput> inputs){admin(u);tenants.inTenant(u.tenantId(),()->{Integer draft=jdbc.queryForObject("SELECT count(*) FROM approval_workflow_version WHERE tenant_id=? AND workflow_id=? AND id=? AND status='DRAFT'",Integer.class,u.tenantId(),id,versionId);if(draft==null||draft==0)throw fail(HttpStatus.CONFLICT,"Only draft workflow versions can be edited");if(inputs.isEmpty()||inputs.size()>30)throw fail(HttpStatus.BAD_REQUEST,"A workflow needs between 1 and 30 steps");Set<Integer> numbers=new HashSet<>();for(StepInput s:inputs){if(!numbers.add(s.stepNo()))throw fail(HttpStatus.BAD_REQUEST,"Step numbers must be unique");if(!Set.of("REVIEW","VERIFY","APPROVE").contains(s.actionType()))throw fail(HttpStatus.BAD_REQUEST,"Invalid step action");if(!Set.of("REPORTING_MANAGER","MANAGER_CHAIN","ROLE","USER").contains(s.approverType()))throw fail(HttpStatus.BAD_REQUEST,"Invalid approver type");if("ROLE".equals(s.approverType())&&(s.roleCode()==null||!Set.of("TENANT_ADMIN","HR_ADMIN","PAYROLL_OFFICER","MANAGER").contains(s.roleCode())))throw fail(HttpStatus.BAD_REQUEST,"Select a supported workspace role");if("USER".equals(s.approverType())&&(s.identityId()==null||!exists("SELECT EXISTS(SELECT 1 FROM auth_identity WHERE tenant_id=? AND id=? AND enabled)",u.tenantId(),s.identityId())))throw fail(HttpStatus.BAD_REQUEST,"Selected approver is not an active workspace user");if("MANAGER_CHAIN".equals(s.approverType())&&(s.managerDepth()==null||s.managerDepth()<1||s.managerDepth()>10))throw fail(HttpStatus.BAD_REQUEST,"Manager depth must be between 1 and 10");}
            List<Integer> sorted=numbers.stream().sorted().toList();for(int i=0;i<sorted.size();i++)if(sorted.get(i)!=i+1)throw fail(HttpStatus.BAD_REQUEST,"Step numbers must be sequential starting at 1");jdbc.update("DELETE FROM approval_workflow_step WHERE tenant_id=? AND workflow_version_id=?",u.tenantId(),versionId);for(StepInput s:inputs)jdbc.update("INSERT INTO approval_workflow_step(tenant_id,workflow_version_id,step_no,label,action_type,approver_type,role_code,identity_id,manager_depth) VALUES(?,?,?,?,?,?,?,?,?)",u.tenantId(),versionId,s.stepNo(),s.label().trim(),s.actionType(),s.approverType(),s.roleCode(),s.identityId(),s.managerDepth());jdbc.update("UPDATE approval_workflow SET updated_at=now() WHERE tenant_id=? AND id=?",u.tenantId(),id);audit(u,"APPROVAL_WORKFLOW_STEPS_UPDATED",versionId);return null;});}
@PostMapping("/workflows/{id}/versions/{versionId}/publish") public void publish(@AuthenticationPrincipal HrmUserPrincipal u,@PathVariable UUID id,@PathVariable UUID versionId){admin(u);tenants.inTenant(u.tenantId(),()->{Integer n=jdbc.queryForObject("SELECT count(*) FROM approval_workflow_step WHERE tenant_id=? AND workflow_version_id=?",Integer.class,u.tenantId(),versionId);if(n==null||n==0)throw fail(HttpStatus.BAD_REQUEST,"Add at least one approval step before publishing");int changed=jdbc.update("UPDATE approval_workflow_version SET status='PUBLISHED',published_by=?,published_at=now() WHERE tenant_id=? AND workflow_id=? AND id=? AND status='DRAFT'",u.id(),u.tenantId(),id,versionId);if(changed==0)throw fail(HttpStatus.CONFLICT,"Workflow version is not a draft");jdbc.update("UPDATE approval_workflow SET status='PUBLISHED',updated_at=now() WHERE tenant_id=? AND id=?",u.tenantId(),id);audit(u,"APPROVAL_WORKFLOW_PUBLISHED",versionId);return null;});}
    @PostMapping("/workflows/{id}/retire") public void retire(@AuthenticationPrincipal HrmUserPrincipal u,@PathVariable UUID id){admin(u);tenants.inTenant(u.tenantId(),()->{int n=jdbc.update("UPDATE approval_workflow SET status='RETIRED',updated_at=now() WHERE tenant_id=? AND id=? AND status<>'RETIRED'",u.tenantId(),id);if(n==0)throw fail(HttpStatus.NOT_FOUND,"Workflow not found");jdbc.update("UPDATE approval_workflow_version SET status='RETIRED' WHERE tenant_id=? AND workflow_id=?",u.tenantId(),id);jdbc.update("UPDATE approval_assignment SET active=false WHERE tenant_id=? AND workflow_version_id IN (SELECT id FROM approval_workflow_version WHERE tenant_id=? AND workflow_id=?)",u.tenantId(),u.tenantId(),id);audit(u,"APPROVAL_WORKFLOW_RETIRED",id);return null;});}
@GetMapping("/assignments") public List<Map<String,Object>> assignments(@AuthenticationPrincipal HrmUserPrincipal u){admin(u);return tenants.inTenant(u.tenantId(),()->jdbc.queryForList("SELECT a.id,a.process_code,a.company_id,c.legal_name AS company_name,a.department_id,d.department_name,a.workflow_version_id,w.name AS workflow_name,v.version_no,a.active FROM approval_assignment a JOIN approval_workflow_version v ON v.tenant_id=a.tenant_id AND v.id=a.workflow_version_id JOIN approval_workflow w ON w.tenant_id=v.tenant_id AND w.id=v.workflow_id LEFT JOIN company c ON c.tenant_id=a.tenant_id AND c.id=a.company_id LEFT JOIN personnel_department d ON d.tenant_id=a.tenant_id AND d.id=a.department_id WHERE a.tenant_id=? ORDER BY a.process_code,a.created_at DESC",u.tenantId()));}
    @PutMapping("/assignments") public Map<String,Object> assign(@AuthenticationPrincipal HrmUserPrincipal u,@Valid @RequestBody AssignmentInput in){admin(u);return tenants.inTenant(u.tenantId(),()->{if(!exists("SELECT EXISTS(SELECT 1 FROM approval_workflow_version v JOIN approval_workflow w ON w.tenant_id=v.tenant_id AND w.id=v.workflow_id WHERE v.tenant_id=? AND v.id=? AND v.status='PUBLISHED' AND w.status='PUBLISHED' AND w.process_code=?)",u.tenantId(),in.workflowVersionId(),in.processCode()))throw fail(HttpStatus.BAD_REQUEST,"Choose a published workflow for this business process");if(in.companyId()!=null&&!exists("SELECT EXISTS(SELECT 1 FROM company WHERE tenant_id=? AND id=?)",u.tenantId(),in.companyId()))throw fail(HttpStatus.BAD_REQUEST,"Company is not in this workspace");if(in.departmentId()!=null&&!exists("SELECT EXISTS(SELECT 1 FROM personnel_department WHERE tenant_id=? AND id=? AND (? IS NULL OR company_id=?))",u.tenantId(),in.departmentId(),in.companyId(),in.companyId()))throw fail(HttpStatus.BAD_REQUEST,"Department is not in the selected company");jdbc.update("DELETE FROM approval_assignment WHERE tenant_id=? AND process_code=? AND company_id IS NOT DISTINCT FROM ? AND department_id IS NOT DISTINCT FROM ?",u.tenantId(),in.processCode(),in.companyId(),in.departmentId());UUID id=UUID.randomUUID();jdbc.update("INSERT INTO approval_assignment(id,tenant_id,process_code,company_id,department_id,workflow_version_id,created_by) VALUES(?,?,?,?,?,?,?)",id,u.tenantId(),in.processCode(),in.companyId(),in.departmentId(),in.workflowVersionId(),u.id());audit(u,"APPROVAL_ASSIGNMENT_UPDATED",id);return Map.of("id",id);});}
@GetMapping("/inbox") public List<Map<String,Object>> inbox(@AuthenticationPrincipal HrmUserPrincipal u){auth(u);return engine.inbox(u.tenantId(),u.id());}
@GetMapping("/my-requests") public List<Map<String,Object>> mine(@AuthenticationPrincipal HrmUserPrincipal u){auth(u);return engine.myRequests(u.tenantId(),u.id());}
@GetMapping("/requests/{instanceId}/history") public List<Map<String,Object>> history(@AuthenticationPrincipal HrmUserPrincipal u,@PathVariable UUID instanceId){auth(u);return engine.history(u.tenantId(),u.id(),instanceId);}
@PostMapping("/tasks/{taskId}/decision") public Map<String,Object> decision(@AuthenticationPrincipal HrmUserPrincipal u,@PathVariable UUID taskId,@Valid @RequestBody DecisionInput in){auth(u);return engine.decide(u.tenantId(),u.id(),taskId,in.decision(),in.comments(),in.approvedMinutes());}
private boolean exists(String sql,Object... args){return Boolean.TRUE.equals(jdbc.queryForObject(sql,Boolean.class,args));}
private void audit(HrmUserPrincipal u,String action,UUID id){jdbc.update("INSERT INTO audit_event(tenant_id,actor_id,action,entity_type,entity_id) VALUES(?,?,?,'approval_workflow',?)",u.tenantId(),u.id(),action,id);}
}
